@MainActor func transient_SlavePadInDevice_frontSideFilledBezierPath (
       _ self_mCenterX : CanariLength,                                
       _ self_mCenterY : CanariLength,                                
       _ self_mWidth : CanariLength,                                  
       _ self_mHeight : CanariLength,                                 
       _ self_mHoleWidth : CanariLength,                              
       _ self_mHoleHeight : CanariLength,                             
       _ self_mShape : PadShape,                                      
       _ self_mStyle : SlavePadStyle
) -> BezierPath {
//--- START OF USER ZONE 2
    let xCenter = self_mCenterX
    let yCenter = self_mCenterY
    let width = self_mWidth
    let height = self_mHeight
    let rPad = CanariRect (left: xCenter - width / 2.0, bottom: yCenter - height / 2.0, width: width, height: height)
    var bp : BezierPath
    switch self_mShape {
    case .rect :
      bp = BezierPath (rect: rPad)
    case .round :
      bp = BezierPath (oblongInRect: rPad)
    case .octo :
      bp = BezierPath (octogonInRect: rPad)
    }
    switch self_mStyle {
    case .traversing :
      let holeWidth = self_mHoleWidth
      let holeHeight = self_mHoleHeight
      let rHole = CanariRect (left: xCenter - holeWidth / 2.0, bottom: yCenter - holeHeight / 2.0, width: holeWidth, height: holeHeight)
      bp.appendOblong (in: rHole)
      bp.windingRule = .evenOdd
    case .componentSide :
      ()
    case .oppositeSide :
      bp = BezierPath ()
    }
    return bp

//--- END OF USER ZONE 2
}

